tiques#Intelligence.html&quot; title=&quot;Int&quot;&gt;Int&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Apprentissage-Rapide.html&quot; title=&quot;Apprentissage rapide&quot;&gt;Apprentissage rapide&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+2 aux tests de comp&#233;tence sans rangs, les comp&#233;tences qui n&#233;cessitent une formation peuvent &#234;tre utilis&#233;s sans&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Limprovisation.html&quot; title=&quot;Science de l&amp;#39;improvisation&quot;&gt;Science de l&#39;improvisation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;Int&quot;&gt;Int&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Apprentissage-Rapide.html&quot; title=&quot;Apprentissage rapide&quot;&gt;Apprentissage rapide&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Improvisation.html&quot; title=&quot;Improvisation&quot;&gt;Improvisation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Les p&#233;nalit&#233;s de non-formation sont divis&#233;es par deux, les bonus d&#39;Improvisation passe &#224; +4&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barrage-De-Styles.html&quot; title=&quot;Barrage de styles&quot;&gt;Barrage de styles&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Bonusdebasealattaque.html&quot; title=&quot;BBA&quot;&gt;BBA&lt;/a&gt; +1, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Les alli&#233;s adjacents diff&#233;rents avec ce don obtiennent un bonus cumulatif de +1 (maximum +4) aux manœuvres offensives&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chance-Insolente.html&quot; title=&quot;Chance insolente&quot;&gt;Chance insolente&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1 fois par jour, relance un 1 naturel&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Chance-Inexplicable.html&quot; title=&quot;Chance inexplicable&quot;&gt;Chance inexplicable&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chance-Insolente.html&quot; title=&quot;Chance insolente&quot;&gt;Chance insolente&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1 fois par jour, +8 avant de faire un jet ou +4 apr&#232;s&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Transmettre-Sa-Chance.html&quot; title=&quot;Transmettre sa chance&quot;&gt;Transmettre sa chance&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chance-Insolente.html&quot; title=&quot;Chance insolente&quot;&gt;Chance insolente&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Chance-Inexplicable.html&quot; title=&quot;Chance inexplicable&quot;&gt;Chance inexplicable&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gain d&#39;une utilisation suppl&#233;mentaire de Chance insolente, utilise Chance inexplicable au profit d&#39;un alli&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Convergence-Magique-&#201;lev&#233;e.html&quot; title=&quot;Convergence magique &#233;lev&#233;e&quot;&gt;Convergence magique &#233;lev&#233;e&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;N&#39;importe quel &lt;a class=&quot;pagelink&quot; href=&quot;Dons.html#DONMETAMAGIE&quot; title=&quot;Les dons&quot;&gt;don de m&#233;tamagie&lt;/a&gt;, 7 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt;, capacit&#233; &#224; lancer des sorts de 2e niveau, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; (garundi)&lt;/td&gt;&lt;td&gt;Applique spontan&#233;ment des dons de m&#233;tamagie sans d&#233;penser d&#39;emplacements de sorts sup&#233;rieurs ou augmenter le temps d&#39;incantation si des alli&#233;s se pr&#233;parent &#224; lancer le m&#234;me sort&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Critiques-Divers.html&quot; title=&quot;Critiques divers&quot;&gt;Critiques divers&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;Guerrier&lt;/a&gt; de niveau 11, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;1 fois par jour, gagne un don de critique&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Curiosit&#233;-Intr&#233;pide.html&quot; title=&quot;Curiosit&#233; intr&#233;pide&quot;&gt;Curiosit&#233; intr&#233;pide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Cha&quot;&gt;Cha&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+1 aux jets de sauvegarde contre les effets d&#39;&#233;motion, nouveaux jets pour r&#233;duire un effet de peur d&#39;un cran&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Assurance-Intimidante.html&quot; title=&quot;Assurance intimidante&quot;&gt;Assurance intimidante&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Cha&quot;&gt;Cha&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Curiosit&#233;-Intr&#233;pide.html&quot; title=&quot;Curiosit&#233; intr&#233;pide&quot;&gt;Curiosit&#233; intr&#233;pide&lt;/a&gt;, 5 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+1 aux jets de sauvegarde contre les effets d&#39;&#233;motion, test d&#39;Intimidation gratuit sur un critique confirm&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Destin-Intr&#233;pide.html&quot; title=&quot;Destin intr&#233;pide&quot;&gt;Destin intr&#233;pide&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Cha&quot;&gt;Cha&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Curiosit&#233;-Intr&#233;pide.html&quot; title=&quot;Curiosit&#233; intr&#233;pide&quot;&gt;Curiosit&#233; intr&#233;pide&lt;/a&gt;, 10 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+1 aux jets de sauvegarde contre les effets d&#39;&#233;motion, relance un 1 naturel 1 fois par jour et peut faire un test d&#39;Intimidation gratuit si le nouveau jet est une r&#233;ussite&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;clectisme.html&quot; title=&quot;&#201;clectisme&quot;&gt;&#201;clectisme&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Gagne une classe de pr&#233;dilection de plus&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Esprit-Unique.html&quot; title=&quot;Esprit unique&quot;&gt;Esprit unique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vigilance.html&quot; title=&quot;Vigilance&quot;&gt;Vigilance&lt;/a&gt;, 3 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; (vudrain)&lt;/td&gt;&lt;td&gt;&#201;vite les malus dus &#224; l&#39;&#233;tat pris au d&#233;pourvu, aveugl&#233; ou en combattant des ennemis invisibles si adjacent &#224; un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Grand-Veneur.html&quot; title=&quot;Grand veneur&quot;&gt;Grand veneur&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;1 rang en &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt;; capacit&#233; de classe &lt;a class=&quot;pagelink&quot; href=&quot;Chasseur.html#COMPAGNONANIMAL&quot; title=&quot;Le chasseur&quot;&gt;compagnon animal&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Paladin.html#PACTEDIVIN&quot; title=&quot;Le paladin&quot;&gt;pacte divin (destrier)&lt;/a&gt;, ou &lt;a class=&quot;pagelink&quot; href=&quot;Chevalier.html#MONTURE&quot; title=&quot;Le chevalier&quot;&gt;monture&lt;/a&gt;; &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+2 aux tests de Dressage et de Connaissances (nature) avec l&#39;animal choisi, augmente le niveau de 1 pour d&#233;terminer les capacit&#233;s du compagnon animal&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;H&#233;ritage-Racial.html&quot; title=&quot;H&#233;ritage racial&quot;&gt;H&#233;ritage racial&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MJRA&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Fonctionne comme un humain et un membre d’une autre race&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Lien-Du-Quah.html&quot; title=&quot;Lien du quah&quot;&gt;Lien du quah&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Totem-Spirituel.html&quot; title=&quot;Totem spirituel&quot;&gt;Totem spirituel&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; (shoanti)&lt;/td&gt;&lt;td&gt;Double les avantages du don Totem spirituel lorsqu&#39;un alli&#233; du m&#234;me quah se trouve &#224; 9 m&#232;tres ou moins&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Loyal-Jusqu&#224;-La-Mort.html&quot; title=&quot;Loyal jusqu&amp;#39;&#224; la mort&quot;&gt;Loyal jusqu&#39;&#224; la mort&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt; (tianais)&lt;/td&gt;&lt;td&gt;Devient la cible d&#39;une attaque dirig&#233;e vers un alli&#233; adjacent qui poss&#232;de ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Opportuniste-Sans-Scrupule.html&quot; title=&quot;Opportuniste sans scrupule&quot;&gt;Opportuniste sans scrupule&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt; (ch&#233;laxien)&lt;/td&gt;&lt;td&gt;L&#39;attaque d&#39;opportunit&#233; r&#233;ussie d&#39;un alli&#233; qui poss&#232;de ce don conf&#232;re un bonus de +2 aux attaques contre le m&#234;me ennemi pendant 1 round&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Polyvalence-Martiale.html&quot; title=&quot;Polyvalence martiale&quot;&gt;Polyvalence martiale&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;Guerrier&lt;/a&gt; de niveau 4, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Un unique don de combat peut &#234;tre appliqu&#233; &#224; toutes les armes du m&#234;me groupe&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;&amp;emsp;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Martiale.html&quot; title=&quot;Ma&#238;trise martiale&quot;&gt;Ma&#238;trise martiale&lt;/a&gt;*&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;Polyvalence martiale, &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt; de niveau 16, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;Les dons de combat peuvent &#234;tre appliqu&#233;s &#224; toutes les armes du m&#234;me groupe&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Poursuite-De-La-Gloire.html&quot; title=&quot;Poursuite de la gloire&quot;&gt;Poursuite de la gloire&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt; (ulfe)&lt;/td&gt;&lt;td&gt;Bonus de moral de +2 aux attaques dans le cadre d&#39;une charge en &#233;tant adjacent &#224; un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejeton-De-Lempire-Perdu.html&quot; title=&quot;Rejeton de l&amp;#39;empire perdu&quot;&gt;Rejeton de l&#39;empire perdu&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt; (ch&#233;laxien ou taldorien)&lt;/td&gt;&lt;td&gt;Bonus de comp&#233;tence de +2 &#224; un jet d&#39;attaque, un jet de sauvegarde, un test de comp&#233;tence ou un test de caract&#233;ristique lorsqu&#39;adjacent &#224; un alli&#233; avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rivalit&#233;-Amicale.html&quot; title=&quot;Rivalit&#233; amicale&quot;&gt;Rivalit&#233; amicale&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt; (taldorien)&lt;/td&gt;&lt;td&gt;Bonus de moral de +2 aux attaques de corps &#224; corps lorsque le personnage est seul &#224; menacer un ennemi et qu&#39;un alli&#233; avec ce don est seul &#224; en menacer un autre&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ruse-Diplomatique.html&quot; title=&quot;Ruse diplomatique&quot;&gt;Ruse diplomatique&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;3 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; (k&#233;l&#233;shite)&lt;/td&gt;&lt;td&gt;Effectue une action libre dans le cadre d&#39;un test d&#39;initiative&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Style-Juju.html&quot; title=&quot;Style juju&quot;&gt;Style juju&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;3 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (religion), &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; (mwangi)&lt;/td&gt;&lt;td&gt;Lance des sorts de contact &#224; 4,5 m&#232;tres s&#39;ils ciblent un alli&#233; mwangi avec ce don&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Succ&#232;s-&#201;clatant.html&quot; title=&quot;Succ&#232;s &#233;clatant&quot;&gt;Succ&#232;s &#233;clatant&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;MR&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;&lt;/td&gt;&lt;td&gt;+2 sur un unique jet apr&#232;s avoir confirm&#233; un coup critique ou avoir obtenu un 20 naturel sur un jet de sauvegarde&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Triangulation.html&quot; title=&quot;Triangulation&quot;&gt;Triangulation&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Combat-En-Aveugle.html&quot; title=&quot;Combat en aveugle&quot;&gt;Combat en aveugle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;trise-Du-Combat-En-Aveugle.html&quot; title=&quot;Ma&#238;trise du combat en aveugle&quot;&gt;Ma&#238;trise du combat en aveugle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Combat-En-Aveugle.html&quot; title=&quot;Science du combat en aveugle&quot;&gt;Science du combat en aveugle&lt;/a&gt;, 15 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;humain&lt;/a&gt; (k&#233;llide)&lt;/td&gt;&lt;td&gt;Localise automatiquement les cr&#233;atures invisibles et relancer les chances de rater dues &#224; un camouflage lorsqu&#39;un alli&#233; avec ce don se trouve &#224; 9 m&#232;tres ou moins&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Troupe-Mortelle.html&quot; title=&quot;Troupe mortelle&quot;&gt;Troupe mortelle&lt;/a&gt;&lt;/td&gt;&lt;td&gt;&lt;sup&gt;&lt;i&gt;ISR&lt;/i&gt;&lt;/sup&gt;&lt;/td&gt;&lt;td&gt;3 rangs en &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;sentation&quot;&gt;Repr&#233;sentation&lt;/a&gt; (com&#233;die) ou en &lt;a class=&quot;pagelink&quot; href=&quot;Repr&#233;sentation.html&quot; title=&quot;Repr&#233;se